class ExampleComponent {
  state = { type: 'a', value: 1 };

  toggleState() {
    if (this.state.type === 'a') {
      this.state = { type: 'b', value: 2 };
    } else {
      this.state = { type: 'a', value: 1 };
    }
  }
}

